-- =====================================================================================
-- Esquema de la base de documentos (cola de FE) — SAP HANA
-- Traducción de db/external/sql_server/schema.sql
--
-- Diferencias respecto a la versión de SQL Server (todas obligadas por el motor):
--
--   * No existe el esquema `dbo`. El script no califica los objetos: se ejecuta sobre
--     el esquema activo (`SET SCHEMA "…";` abajo).
--   * Identificadores entre comillas dobles para preservar el CamelCase. Sin comillas,
--     HANA los pasa a MAYÚSCULAS y las columnas volverían como DOCENTRY, SAPDB, etc.
--     ⚠️ Todo consumidor (ODBC, Service Layer, procedimientos) debe citarlos igual.
--   * `NVARCHAR(MAX)` → `NVARCHAR(5000)` (tope de NVARCHAR en HANA). Si algún detalle
--     de Hacienda pudiera exceder 5000 caracteres, la columna debe ser `NCLOB` — a
--     cambio de tener que leerla como LOB desde ODBC.
--   * `DATETIME2(3)` → `TIMESTAMP` (precisión de 7 dígitos, no 3).
--   * `SYSDATETIME()` / `GETDATE()` → `CURRENT_TIMESTAMP`.
--   * `DATEADD(MINUTE, -10, …)` → `ADD_SECONDS(…, -600)`; HANA no tiene `ADD_MINUTES`.
--   * `PRIMARY KEY CLUSTERED` → `PRIMARY KEY`. HANA no tiene índice clustered; el
--     almacenamiento lo define `COLUMN TABLE` / `ROW TABLE`.
--   * `CREATE NONCLUSTERED INDEX … INCLUDE (…)` → `CREATE INDEX` sin `INCLUDE`. HANA no
--     tiene columnas incluidas: en un column table cada columna se lee por separado, así
--     que el covering index no aplica.
--   * `IDENTITY(1,1)` → `GENERATED BY DEFAULT AS IDENTITY`.
--   * `INSERT … VALUES (…),(…),(…)` → un `INSERT` por fila. HANA no acepta VALUES multi-fila.
--   * `IF EXISTS (SELECT …)` no existe en SQLScript → `SELECT COUNT(*) INTO <var>` + `IF`.
--   * `UPDATE … OUTPUT inserted.*` no existe en HANA → ver el comentario de
--     CL_D_CL_MLT_FEC_SLT_PENDINGDOCUMENTS.
--   * La FK declara `ON UPDATE RESTRICT ON DELETE RESTRICT` de forma explícita: el
--     default de HANA para `ON UPDATE` es CASCADE, no NO ACTION como en SQL Server.
--   * Sin `GO`, sin `SET ANSI_NULLS` / `SET QUOTED_IDENTIFIER` (no existen). Cada
--     sentencia termina en `;`.
--
-- Despliegue:  hdbsql -n <host>:3<NN>15 -u <user> -p <pass> -I db/external/hana/schema.sql
-- =====================================================================================

-- SET SCHEMA "CL_FEC_DOCS";   -- descomentar y ajustar al esquema de la instalación

-- Redespliegue (descomentar solo si se quiere recrear desde cero — borra los datos):
-- DROP PROCEDURE "CL_D_CL_MLT_FEC_UPT_DOCUMENT";
-- DROP PROCEDURE "CL_D_CL_MLT_FEC_SLT_PENDINGDOCUMENTS";
-- DROP PROCEDURE "CL_D_CL_MLT_FEC_CRT_DOCUMENTTOQUEUE";
-- DROP TABLE "DocumentsQueue";
-- DROP TABLE "StatusCodes";
-- DROP TABLE "DocTypes";


-- 1. Tabla Catálogo de Estados (PK Tinyint Manual)
CREATE COLUMN TABLE "StatusCodes" (
    "Code"        TINYINT       NOT NULL,
    "Name"        NVARCHAR(20)  NOT NULL,
    "Description" NVARCHAR(255) NOT NULL,
    CONSTRAINT "PK_StatusCodes" PRIMARY KEY ("Code")
);

-- Inserción de Estados (HANA no soporta VALUES multi-fila: un INSERT por estado)
--
-- `Sent` (3) es de TRÁNSITO, no final: se envió el comprobante y todavía no
-- hay respuesta de Hacienda (equivale a "EnHacienda" del sistema legacy).
-- `Accepted`/`Rejected` sí son finales.
INSERT INTO "StatusCodes" ("Code", "Name", "Description") VALUES
(0, 'Pending', 'Documento registrado por SAP, listo para ser procesado.');
INSERT INTO "StatusCodes" ("Code", "Name", "Description") VALUES
(1, 'OnHold', 'En espera por conflicto de concurrencia (un intento anterior del mismo documento está en Processing).');
INSERT INTO "StatusCodes" ("Code", "Name", "Description") VALUES
(2, 'Processing', 'Documento en proceso activo de consulta, validación o envío a Hacienda.');
INSERT INTO "StatusCodes" ("Code", "Name", "Description") VALUES
(3, 'Sent', 'Documento enviado a Hacienda; todavía sin respuesta de aceptación o rechazo (equivale a "EnHacienda" del sistema legacy).');
INSERT INTO "StatusCodes" ("Code", "Name", "Description") VALUES
(4, 'Error', 'Fallo de validación o error técnico.');
INSERT INTO "StatusCodes" ("Code", "Name", "Description") VALUES
(5, 'Cancelled', 'Documento descartado u omitido porque un intento previo ya finalizó con éxito.');
INSERT INTO "StatusCodes" ("Code", "Name", "Description") VALUES
(6, 'Accepted', 'Hacienda aceptó el comprobante.');
INSERT INTO "StatusCodes" ("Code", "Name", "Description") VALUES
(7, 'Rejected', 'Hacienda rechazó el comprobante.');


-- 2. Tabla Catálogo de Tipos de Documento (PK Nvarchar Manual)
--
-- Espejo de `DocType` (app/models/doc_type.rb) — pero solo de los códigos que
-- SÍ son comprobantes encolables. Los tres mensajes de receptor (`05`/`06`/`07`,
-- `DocType::RECEIVER_MESSAGES`) no llevan `DocEntry` de factura ni pasan por
-- esta cola: no tienen detalle de líneas ni resumen, así que no son un
-- "tipo de documento" para `DocumentsQueue` (mismo criterio que ya aplica
-- `db/seeds.rb` para `qsSlUpdateDocumentInfo`). Si `DocType` agrega o quita un
-- comprobante real, este catálogo se actualiza junto con él. HANA no acepta
-- VALUES multi-fila: un INSERT por código.
CREATE COLUMN TABLE "DocTypes" (
    "Code"        NVARCHAR(2)   NOT NULL,
    "Name"        NVARCHAR(10)  NOT NULL,
    "Description" NVARCHAR(255) NOT NULL,
    CONSTRAINT "PK_DocTypes" PRIMARY KEY ("Code")
);

INSERT INTO "DocTypes" ("Code", "Name", "Description") VALUES
('01', 'FE', 'Factura electrónica');
INSERT INTO "DocTypes" ("Code", "Name", "Description") VALUES
('02', 'ND', 'Nota de débito electrónica');
INSERT INTO "DocTypes" ("Code", "Name", "Description") VALUES
('03', 'NC', 'Nota de crédito electrónica');
INSERT INTO "DocTypes" ("Code", "Name", "Description") VALUES
('04', 'TE', 'Tiquete electrónico');
INSERT INTO "DocTypes" ("Code", "Name", "Description") VALUES
('08', 'FEC', 'Factura electrónica de compra');
INSERT INTO "DocTypes" ("Code", "Name", "Description") VALUES
('09', 'FEE', 'Factura electrónica de exportación');
INSERT INTO "DocTypes" ("Code", "Name", "Description") VALUES
('10', 'REP', 'Recibo electrónico de pago');


-- 3. Tabla Principal de Cola de Documentos
--
-- COLUMN TABLE es el default recomendado por SAP. Si el volumen de UPDATE por fila
-- llegara a ser el cuello de botella (cola muy caliente, delta merge constante),
-- la alternativa es ROW TABLE — misma definición, solo cambia la palabra.
CREATE COLUMN TABLE "DocumentsQueue" (
    "Id"         BIGINT         GENERATED BY DEFAULT AS IDENTITY (START WITH 1 INCREMENT BY 1) NOT NULL,
    "DocEntry"   INTEGER        NOT NULL,
    "DocType"    NVARCHAR(2)    NOT NULL,
    "SAPDB"      NVARCHAR(30)   NOT NULL,
    "StatusCode" TINYINT        DEFAULT 0 NOT NULL,
    "Details"    NVARCHAR(5000),
    "CreatedAt"  TIMESTAMP      DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "UpdatedAt"  TIMESTAMP      DEFAULT CURRENT_TIMESTAMP NOT NULL,

    CONSTRAINT "PK_DocumentsQueue" PRIMARY KEY ("Id")
);

ALTER TABLE "DocumentsQueue"
    ADD CONSTRAINT "FK_DocumentsQueue_StatusCodes" FOREIGN KEY ("StatusCode")
        REFERENCES "StatusCodes" ("Code") ON UPDATE RESTRICT ON DELETE RESTRICT;

ALTER TABLE "DocumentsQueue"
    ADD CONSTRAINT "FK_DocumentsQueue_DocTypes" FOREIGN KEY ("DocType")
        REFERENCES "DocTypes" ("Code") ON UPDATE RESTRICT ON DELETE RESTRICT;


-- 4. Índices de Rendimiento

-- Optimiza la lectura de documentos pendientes/encolados por el FE Service.
-- Sin INCLUDE (DocEntry, DocType): en un column table no hay covering index, cada
-- columna se lee de su propio vector.
CREATE INDEX "IX_DocumentsQueue_Polling"
ON "DocumentsQueue" ("SAPDB", "StatusCode", "Id");

-- Optimiza la búsqueda de historial/trazabilidad por documento.
-- Sin `CreatedAt DESC`: el índice de un column table es un inverted index, no guarda
-- orden, así que la dirección la resuelve el ORDER BY de la consulta.
CREATE INDEX "IX_DocumentsQueue_DocLookup"
ON "DocumentsQueue" ("SAPDB", "DocType", "DocEntry", "CreatedAt");


-- =====================================================================================
-- Procedimiento: CL_D_CL_MLT_FEC_CRT_DOCUMENTTOQUEUE
-- Encola un documento enviado por SAP.
--
-- `IF EXISTS (SELECT …)` no existe en SQLScript: se cuenta en una variable escalar.
-- El `SELECT TOP(1) 1 … ORDER BY Id DESC` del original se traduce a un COUNT(*): el
-- ORDER BY y el TOP no cambiaban el resultado de la prueba de existencia.
-- =====================================================================================
CREATE PROCEDURE "CL_D_CL_MLT_FEC_CRT_DOCUMENTTOQUEUE" (
    IN IV_SAPDB    NVARCHAR(30),
    IN IV_DOCENTRY INTEGER,
    IN IV_DOCTYPE  NVARCHAR(2)
)
LANGUAGE SQLSCRIPT AS
BEGIN
    DECLARE lv_processing INTEGER;
    DECLARE lv_blocking   INTEGER;

    SELECT COUNT(*) INTO lv_processing
      FROM "DocumentsQueue"
     WHERE "SAPDB"      = :IV_SAPDB
       AND "DocEntry"   = :IV_DOCENTRY
       AND "DocType"    = :IV_DOCTYPE
       AND "StatusCode" = 2;

    IF :lv_processing > 0 THEN
        /*
            Se guarda en estado OnHold debido a que no sabemos si el documento duplicado
            que esta en estado Processing se procesara correctamente, por lo cual no
            podemos dejarlo en "Pending" provocando que otro proceso lo tome y lo
            procese duplicado.
        */
        INSERT INTO "DocumentsQueue"
               ("DocEntry", "DocType", "SAPDB", "StatusCode", "CreatedAt", "UpdatedAt")
        VALUES (:IV_DOCENTRY, :IV_DOCTYPE, :IV_SAPDB, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
    ELSE
        SELECT COUNT(*) INTO lv_blocking
          FROM "DocumentsQueue"
         WHERE "SAPDB"    = :IV_SAPDB
           AND "DocEntry" = :IV_DOCENTRY
           AND "DocType"  = :IV_DOCTYPE
           AND "StatusCode" NOT IN (0, 3);

        IF :lv_blocking = 0 THEN
            INSERT INTO "DocumentsQueue"
                   ("DocEntry", "DocType", "SAPDB", "StatusCode", "CreatedAt", "UpdatedAt")
            VALUES (:IV_DOCENTRY, :IV_DOCTYPE, :IV_SAPDB, 0, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
        END IF;
    END IF;
END;


-- =====================================================================================
-- Procedimiento: CL_D_CL_MLT_FEC_SLT_PENDINGDOCUMENTS
-- Reclama los documentos pendientes (o los que quedaron colgados en Processing más de
-- 10 minutos), los marca en Processing y devuelve los que reclamó ESTA llamada.
--
-- HANA no tiene la cláusula `OUTPUT inserted.*`, así que el reclamo se hace en dos
-- pasos con una MARCA: se sella `UpdatedAt` con un valor fijo de esta llamada
-- (`lv_now`) y después se leen exactamente las filas que quedaron con ese sello.
--
-- Por qué no hay doble reclamo: en READ COMMITTED, un UPDATE concurrente sobre una fila
-- ya bloqueada espera al commit del primero y REEVALÚA el WHERE con la versión nueva —
-- la fila ya está en StatusCode 2 con UpdatedAt reciente, así que queda fuera.
--
-- Límite conocido: si dos llamadas obtuvieran el mismo `CURRENT_TIMESTAMP` (resolución
-- de 100 ns), cada una vería también las filas de la otra. Si eso llegara a importar,
-- lo robusto es una columna `ClaimToken` propia sellada con un valor único por llamada,
-- en vez de reutilizar `UpdatedAt` como marca.
--
-- El parámetro OUT de tipo TABLE le llega al cliente (ODBC / .NET) como result set,
-- igual que el OUTPUT del original. Un `SELECT` suelto al final del cuerpo también
-- devolvería un result set implícito, pero sin contrato declarado.
-- =====================================================================================
CREATE PROCEDURE "CL_D_CL_MLT_FEC_SLT_PENDINGDOCUMENTS" (
    OUT ET_DOCUMENTS TABLE (
        "Id"       BIGINT,
        "DocEntry" INTEGER,
        "DocType"  NVARCHAR(2),
        "SAPDB"    NVARCHAR(30)
    )
)
LANGUAGE SQLSCRIPT AS
BEGIN
    DECLARE lv_now          TIMESTAMP;
    DECLARE lv_stale_before TIMESTAMP;

    lv_now          := CURRENT_TIMESTAMP;
    lv_stale_before := ADD_SECONDS(:lv_now, -600);   -- DATEADD(MINUTE, -10, GETDATE())

    UPDATE "DocumentsQueue"
       SET "StatusCode" = 2,
           "UpdatedAt"  = :lv_now
     WHERE "StatusCode" = 0
        OR ("StatusCode" = 2 AND "UpdatedAt" <= :lv_stale_before);

    ET_DOCUMENTS =
        SELECT "Id", "DocEntry", "DocType", "SAPDB"
          FROM "DocumentsQueue"
         WHERE "StatusCode" = 2
           AND "UpdatedAt"  = :lv_now;
END;


-- =====================================================================================
-- Procedimiento: CL_D_CL_MLT_FEC_UPT_DOCUMENT
-- Actualiza el resultado de un documento y resuelve los duplicados que quedaron OnHold.
--
-- `@Id` se declara BIGINT (no INT como en el original): es el tipo real de la columna.
-- =====================================================================================
CREATE PROCEDURE "CL_D_CL_MLT_FEC_UPT_DOCUMENT" (
    IN IV_ID         BIGINT,
    IN IV_DOCENTRY   INTEGER,
    IN IV_DOCTYPE    NVARCHAR(2),
    IN IV_SAPDB      NVARCHAR(30),
    IN IV_DETAILS    NVARCHAR(5000),
    IN IV_STATUSCODE TINYINT
)
LANGUAGE SQLSCRIPT AS
BEGIN
    UPDATE "DocumentsQueue"
       SET "StatusCode" = :IV_STATUSCODE,
           "Details"    = :IV_DETAILS,
           "UpdatedAt"  = CURRENT_TIMESTAMP
     WHERE "Id" = :IV_ID;

    IF :IV_STATUSCODE = 3 THEN
        UPDATE "DocumentsQueue"
           SET "StatusCode" = 5,
               "Details"    = 'Este documento ya fué procesado exitosamente.',
               "UpdatedAt"  = CURRENT_TIMESTAMP
         WHERE "SAPDB"      = :IV_SAPDB
           AND "DocEntry"   = :IV_DOCENTRY
           AND "DocType"    = :IV_DOCTYPE
           AND "StatusCode" = 1;

    ELSEIF :IV_STATUSCODE = 4 THEN
        UPDATE "DocumentsQueue"
           SET "StatusCode" = 0,
               "Details"    = NULL,
               "UpdatedAt"  = CURRENT_TIMESTAMP
         WHERE "SAPDB"      = :IV_SAPDB
           AND "DocEntry"   = :IV_DOCENTRY
           AND "DocType"    = :IV_DOCTYPE
           AND "StatusCode" = 1;
    END IF;
END;
